const raw = $json.text;

try {
  const parsed = JSON.parse(raw);

  return {
    json: parsed
  };
}
catch (e) {
  return {
    json: {
      intent: "unknown_intent",
      confidence: 0,
      agent: "Escalation",
      action_required: false,
      reason: "Invalid JSON from model"
